def moore_bound(d, g):
    n = 1
    if g % 2 == 1:
        k = (g - 1) // 2
        n += d * sum((d - 1)**i for i in range(k))
    else:
        k = g // 2
        n += d * sum((d - 1)**i for i in range(k - 1)) + (d - 1)**(k - 1)
    return n

print("Moore bound for d=3, g=7:", moore_bound(3, 7))

